 1	/**
 2	 * WP-009: New Test Suite — Repository Scope Integration Tests
 3	 *
 4	 * 31 test cases covering repository scope functionality across two layers:
 5	 *
 6	 * Storage layer (KnowledgeStoreManager) — 16 cases:
 7	 *   - repositoryStorePath path generation and reserved-name guard
 8	 *   - addInsight with repository scope (success and missing-repository_name error)
 9	 *   - readRepositoryStore empty and populated
10	 *   - listInsights unfiltered, scope-filtered, and name-filtered
11	 *   - searchInsights with repository_name
12	 *   - updateInsight and deleteInsight with repository scope
13	 *   - moveInsight global→repo, repo→repo, and same-name rejection
14	 *   - origin_plan preservation through add, update, and move
15	 *
16	 * GUI REST handlers (gui/api-knowledge.ts) — 10 cases:
17	 *   - handleListKnowledge with repository_name
18	 *   - handleUpdateKnowledge with repository scope and repository_name
19	 *   - handleDeleteKnowledge with repository scope (success and missing repository_name)
20	 *   - handlePromoteKnowledge from repository (success) and from global (rejection)
21	 *   - handleMoveKnowledge global→repo, repo→repo same-name rejection,
22	 *     missing target_repository_name rejection
23	 *   - scope: 'project' rejection by all handlers
24	 *
25	 * Uses real temp directories (mkdtemp/rm) and KnowledgeStoreManager — no mocks.
26	 * Follows the pattern established in tests/gui/knowledge-api.test.ts.
27	 */
28	
29	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
30	import { mkdtemp, rm } from 'fs/promises';
31	import { join } from 'path';
32	import { tmpdir } from 'os';
33	
34	import {
35	  handleListKnowledge,
36	  handleUpdateKnowledge,
37	  handleDeleteKnowledge,
38	  handlePromoteKnowledge,
39	  handleMoveKnowledge,
40	} from '../../gui/api-knowledge.js';
41	import { KnowledgeStoreManager } from '../../src/storage/knowledge-store.js';
42	import type { Insight } from '../../src/schema/knowledge.js';
43	
44	// ---------------------------------------------------------------------------
45	// Helpers
46	// ---------------------------------------------------------------------------
47	
48	/** Build a minimal valid insight input (no id). */
49	function makeInsightInput(overrides: Partial<Omit<Insight, 'id'>> = {}): Omit<Insight, 'id'> {
50	  return {
51	    scope: 'global',
52	    title: 'Default title',
53	    content: 'Default content',
54	    category: 'general',
55	    tags: [],
56	    source: 'test',
57	    created_at: '2026-01-01T00:00:00Z',
58	    confidence: 0.8,
59	    ...overrides,
60	  };
61	}
62	
63	// ---------------------------------------------------------------------------
64	// Storage layer — repositoryStorePath
65	// ---------------------------------------------------------------------------
66	
67	describe('KnowledgeStoreManager.repositoryStorePath', () => {
68	  let ledgerRoot: string;
69	  let manager: KnowledgeStoreManager;
70	
71	  beforeEach(async () => {
72	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-path-'));
73	    manager = new KnowledgeStoreManager(ledgerRoot);
74	  });
75	
76	  afterEach(async () => {
77	    await rm(ledgerRoot, { recursive: true, force: true });
78	  });
79	
80	  it("returns {knowledgeDir}/{repoName}-insights.json for a valid repository name", () => {
81	    const storePath = manager.repositoryStorePath('hcp-editor');
82	    const expected = join(manager.knowledgeDir(), 'hcp-editor-insights.json');
83	    expect(storePath).toBe(expected);
84	  });
85	
86	  it("throws for the reserved name 'global'", () => {
87	    expect(() => manager.repositoryStorePath('global')).toThrow(
88	      "'global' is a reserved name and cannot be used as a repository name."
89	    );
90	  });
91	});
92	
93	// ---------------------------------------------------------------------------
94	// Storage layer — addInsight (repository scope)
95	// ---------------------------------------------------------------------------
96	
97	describe('KnowledgeStoreManager.addInsight — repository scope', () => {
98	  let ledgerRoot: string;
99	  let manager: KnowledgeStoreManager;

101	  beforeEach(async () => {
102	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-add-'));
103	    manager = new KnowledgeStoreManager(ledgerRoot);
104	  });
105	
106	  afterEach(async () => {
107	    await rm(ledgerRoot, { recursive: true, force: true });
108	  });
109	
110	  it('creates repository store file with correct fields including origin_plan', async () => {
111	    const insight = await manager.addInsight(
112	      makeInsightInput({
113	        scope: 'repository',
114	        repository_name: 'hcp-editor',
115	        origin_plan: 'my-plan',
116	        title: 'Codebase insight',
117	      })
118	    );
119	
120	    expect(insight.scope).toBe('repository');
121	    expect(insight.repository_name).toBe('hcp-editor');
122	    expect(insight.origin_plan).toBe('my-plan');
123	    expect(insight.title).toBe('Codebase insight');
124	    expect(insight.id).toBeTypeOf('number');
125	    expect(insight.id).toBeGreaterThan(0);
126	
127	    // Verify the file was written in the correct location
128	    const store = await manager.readRepositoryStore('hcp-editor');
129	    expect(store.insights).toHaveLength(1);
130	    expect(store.insights[0]!.title).toBe('Codebase insight');
131	  });
132	
133	  it('throws when repository_name is absent for repository-scoped insight', async () => {
134	    await expect(
135	      manager.addInsight(
136	        makeInsightInput({ scope: 'repository' /* no repository_name */ })
137	      )
138	    ).rejects.toThrow('repository_name is required for repository-scoped insights');
139	  });
140	});
141	
142	// ---------------------------------------------------------------------------
143	// Storage layer — readRepositoryStore
144	// ---------------------------------------------------------------------------
145	
146	describe('KnowledgeStoreManager.readRepositoryStore', () => {
147	  let ledgerRoot: string;
148	  let manager: KnowledgeStoreManager;
149	
150	  beforeEach(async () => {
151	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-read-'));
152	    manager = new KnowledgeStoreManager(ledgerRoot);
153	  });
154	
155	  afterEach(async () => {
156	    await rm(ledgerRoot, { recursive: true, force: true });
157	  });
158	
159	  it('returns empty store when repository file does not exist', async () => {
160	    const store = await manager.readRepositoryStore('hcp-editor');
161	    expect(store.insights).toEqual([]);
162	    expect(store.next_id).toBe(1);
163	  });
164	
165	  it('returns stored insights after addInsight', async () => {
166	    await manager.addInsight(
167	      makeInsightInput({ scope: 'repository', repository_name: 'hcp-editor', title: 'First' })
168	    );
169	    await manager.addInsight(
170	      makeInsightInput({ scope: 'repository', repository_name: 'hcp-editor', title: 'Second' })
171	    );
172	
173	    const store = await manager.readRepositoryStore('hcp-editor');
174	    expect(store.insights).toHaveLength(2);
175	    const titles = store.insights.map((i) => i.title);
176	    expect(titles).toContain('First');
177	    expect(titles).toContain('Second');
178	  });
179	});
180	
181	// ---------------------------------------------------------------------------
182	// Storage layer — listInsights (scope and repository_name filtering)
183	// ---------------------------------------------------------------------------
184	
185	describe('KnowledgeStoreManager.listInsights — repository scope filtering', () => {
186	  let ledgerRoot: string;
187	  let manager: KnowledgeStoreManager;
188	
189	  beforeEach(async () => {
190	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-list-'));
191	    manager = new KnowledgeStoreManager(ledgerRoot);
192	  });
193	
194	  afterEach(async () => {
195	    await rm(ledgerRoot, { recursive: true, force: true });
196	  });
197	
198	  it('no filters returns global + all repository insights', async () => {
199	    await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global' }));
200	    await manager.addInsight(
201	      makeInsightInput({ scope: 'repository', repository_name: 'alpha', title: 'Alpha insight' })
202	    );
203	    await manager.addInsight(
204	      makeInsightInput({ scope: 'repository', repository_name: 'beta', title: 'Beta insight' })
205	    );
206	
207	    const results = await manager.listInsights({});
208	    expect(results).toHaveLength(3);
209	    const titles = results.map((i) => i.title);
210	    expect(titles).toContain('Global');
211	    expect(titles).toContain('Alpha insight');
212	    expect(titles).toContain('Beta insight');
213	  });
214	
215	  it('scope:repository returns only repository-scoped insights', async () => {
216	    await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global' }));
217	    await manager.addInsight(
218	      makeInsightInput({ scope: 'repository', repository_name: 'alpha', title: 'Alpha' })
219	    );
220	    await manager.addInsight(
221	      makeInsightInput({ scope: 'repository', repository_name: 'beta', title: 'Beta' })
222	    );
223	
224	    const results = await manager.listInsights({ scope: 'repository' });
225	    expect(results).toHaveLength(2);
226	    expect(results.every((i) => i.scope === 'repository')).toBe(true);
227	  });
228	
229	  it('scope:repository + repository_name narrows to one store', async () => {
230	    await manager.addInsight(
231	      makeInsightInput({ scope: 'repository', repository_name: 'hcp-editor', title: 'HCP insight' })
232	    );
233	    await manager.addInsight(
234	      makeInsightInput({ scope: 'repository', repository_name: 'other-repo', title: 'Other' })
235	    );
236	
237	    const results = await manager.listInsights({ scope: 'repository', repository_name: 'hcp-editor' });
238	    expect(results).toHaveLength(1);
239	    expect(results[0]!.title).toBe('HCP insight');
240	    expect(results[0]!.repository_name).toBe('hcp-editor');
241	  });
242	});
243	
244	// ---------------------------------------------------------------------------
245	// Storage layer — searchInsights with repository_name
246	// ---------------------------------------------------------------------------
247	
248	describe('KnowledgeStoreManager.searchInsights — repository_name filter', () => {
249	  let ledgerRoot: string;
250	  let manager: KnowledgeStoreManager;

251	
252	  beforeEach(async () => {
253	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-search-'));
254	    manager = new KnowledgeStoreManager(ledgerRoot);
255	  });
256	
257	  afterEach(async () => {
258	    await rm(ledgerRoot, { recursive: true, force: true });
259	  });
260	
261	  it('searches only the specified repository store', async () => {
262	    await manager.addInsight(
263	      makeInsightInput({
264	        scope: 'repository',
265	        repository_name: 'hcp-editor',
266	        title: 'Atomic writes pattern',
267	        content: 'Use atomic writes for safe file updates.',
268	      })
269	    );
270	    await manager.addInsight(
271	      makeInsightInput({
272	        scope: 'repository',
273	        repository_name: 'other-repo',
274	        title: 'Atomic file operations',
275	        content: 'Other repo content about atomicity.',
276	      })
277	    );
278	
279	    const results = await manager.searchInsights('atomic', { repository_name: 'hcp-editor' });
280	    expect(results).toHaveLength(1);
281	    expect(results[0]!.repository_name).toBe('hcp-editor');
282	    expect(results[0]!.title).toBe('Atomic writes pattern');
283	  });
284	});
285	
286	// ---------------------------------------------------------------------------
287	// Storage layer — updateInsight with repository scope
288	// ---------------------------------------------------------------------------
289	
290	describe('KnowledgeStoreManager.updateInsight — repository scope', () => {
291	  let ledgerRoot: string;
292	  let manager: KnowledgeStoreManager;
293	
294	  beforeEach(async () => {
295	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-update-'));
296	    manager = new KnowledgeStoreManager(ledgerRoot);
297	  });
298	
299	  afterEach(async () => {
300	    await rm(ledgerRoot, { recursive: true, force: true });
301	  });
302	
303	  it('updates insight in repository store correctly', async () => {
304	    const created = await manager.addInsight(
305	      makeInsightInput({
306	        scope: 'repository',
307	        repository_name: 'hcp-editor',
308	        title: 'Original title',
309	      })
310	    );
311	
312	    const updated = await manager.updateInsight(
313	      created.id,
314	      { title: 'Updated title' },
315	      { scope: 'repository', repository_name: 'hcp-editor' }
316	    );
317	
318	    expect(updated.id).toBe(created.id);
319	    expect(updated.title).toBe('Updated title');
320	    expect(updated.scope).toBe('repository');
321	    expect(updated.repository_name).toBe('hcp-editor');
322	  });
323	});
324	
325	// ---------------------------------------------------------------------------
326	// Storage layer — deleteInsight with repository scope
327	// ---------------------------------------------------------------------------
328	
329	describe('KnowledgeStoreManager.deleteInsight — repository scope', () => {
330	  let ledgerRoot: string;
331	  let manager: KnowledgeStoreManager;
332	
333	  beforeEach(async () => {
334	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-delete-'));
335	    manager = new KnowledgeStoreManager(ledgerRoot);
336	  });
337	
338	  afterEach(async () => {
339	    await rm(ledgerRoot, { recursive: true, force: true });
340	  });
341	
342	  it('removes insight from repository store', async () => {
343	    const created = await manager.addInsight(
344	      makeInsightInput({
345	        scope: 'repository',
346	        repository_name: 'hcp-editor',
347	        title: 'To delete',
348	      })
349	    );
350	
351	    await manager.deleteInsight(created.id, { scope: 'repository', repository_name: 'hcp-editor' });
352	
353	    const remaining = await manager.listInsights({ scope: 'repository', repository_name: 'hcp-editor' });
354	    expect(remaining).toHaveLength(0);
355	  });
356	});
357	
358	// ---------------------------------------------------------------------------
359	// Storage layer — moveInsight (global ↔ repository, repo ↔ repo)
360	// ---------------------------------------------------------------------------
361	
362	describe('KnowledgeStoreManager.moveInsight — repository scope', () => {
363	  let ledgerRoot: string;
364	  let manager: KnowledgeStoreManager;
365	
366	  beforeEach(async () => {
367	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-move-'));
368	    manager = new KnowledgeStoreManager(ledgerRoot);
369	  });
370	
371	  afterEach(async () => {
372	    await rm(ledgerRoot, { recursive: true, force: true });
373	  });
374	
375	  it('moves global insight to repository (global → repository)', async () => {
376	    const global = await manager.addInsight(
377	      makeInsightInput({ scope: 'global', title: 'Will move to repo' })
378	    );
379	
380	    const moved = await manager.moveInsight(
381	      global.id,
382	      { scope: 'global' },
383	      'repository',
384	      'hcp-editor'
385	    );
386	
387	    expect(moved.scope).toBe('repository');
388	    expect(moved.repository_name).toBe('hcp-editor');
389	    expect(moved.title).toBe('Will move to repo');
390	
391	    // Original global insight is removed
392	    const globalInsights = await manager.listInsights({ scope: 'global' });
393	    expect(globalInsights).toHaveLength(0);
394	
395	    // Insight now lives in the repository store
396	    const repoInsights = await manager.listInsights({ scope: 'repository', repository_name: 'hcp-editor' });
397	    expect(repoInsights).toHaveLength(1);
398	    expect(repoInsights[0]!.title).toBe('Will move to repo');
399	  });

401	  it('moves repository insight to different repository (repository → repository)', async () => {
402	    const original = await manager.addInsight(
403	      makeInsightInput({
404	        scope: 'repository',
405	        repository_name: 'repo-a',
406	        title: 'Cross-repo move',
407	      })
408	    );
409	
410	    const moved = await manager.moveInsight(
411	      original.id,
412	      { scope: 'repository', repository_name: 'repo-a' },
413	      'repository',
414	      'repo-b'
415	    );
416	
417	    expect(moved.scope).toBe('repository');
418	    expect(moved.repository_name).toBe('repo-b');
419	    expect(moved.title).toBe('Cross-repo move');
420	
421	    const repoAInsights = await manager.listInsights({ scope: 'repository', repository_name: 'repo-a' });
422	    expect(repoAInsights).toHaveLength(0);
423	
424	    const repoBInsights = await manager.listInsights({ scope: 'repository', repository_name: 'repo-b' });
425	    expect(repoBInsights).toHaveLength(1);
426	  });
427	
428	  it('throws when moving repository insight to the same repository (identity move)', async () => {
429	    await expect(
430	      manager.moveInsight(
431	        1,
432	        { scope: 'repository', repository_name: 'same-repo' },
433	        'repository',
434	        'same-repo'
435	      )
436	    ).rejects.toThrow();
437	  });
438	});
439	
440	// ---------------------------------------------------------------------------
441	// Storage layer — origin_plan preservation through add, update, and move
442	// ---------------------------------------------------------------------------
443	
444	describe('KnowledgeStoreManager — origin_plan provenance preservation', () => {
445	  let ledgerRoot: string;
446	  let manager: KnowledgeStoreManager;
447	
448	  beforeEach(async () => {
449	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-origin-'));
450	    manager = new KnowledgeStoreManager(ledgerRoot);
451	  });
452	
453	  afterEach(async () => {
454	    await rm(ledgerRoot, { recursive: true, force: true });
